@block PandaPD begin
    # 1 kHz joint controller of the Panda (sampled firmware, D28): PD on the IK reference plus
    # gravity and friction feedforward from the Gaz et al. 2019 model. Generated by
    # design/build_library.py (gains and parameters from design.py / panda.py).
    #
    #   qdr_i = (qr_i - qr_i at the previous tick) / dt                  reference rate
    #   u_i   = clamp(Kp_i (qr_i - q_i) + Kd_i (qdr_i - dq_i) + G_i(q) + kf tau_f,i(qdr_i), +-umax_i)
    #
    # G(q) is the torque that holds the arm static: the forward kinematics of the modified-DH
    # chain is unrolled below and G_i = g0 sum_{j>=i} m_j z_i . ((c_j - o_i) x e_z), with the
    # Gaz masses and centres of mass (checked against the Newton-Euler of design/panda.py and
    # against MuJoCo, design/validate.py). tau_f is the Gaz friction law at the reference rate.
    # Kp = B wn^2 and Kd = 2 B wn with B the largest M_ii + N^2 J_m along the joint path.
    @parameters begin
        Kp1::Real = 320.35, [unit = "N*m/rad", min = 0, description = "Joint 1 proportional gain"]
        Kd1::Real = 42.713, [unit = "N*m*s/rad", min = 0, description = "Joint 1 rate gain"]
        u1max::Real = 87.0, [unit = "N*m", min = 0, description = "Joint 1 torque limit (Franka)"]
        fa1::Real = 0.54615, [unit = "N*m", min = 0, description = "Joint 1 friction level (Gaz phi1)"]
        fb1::Real = 5.1181, [unit = "s/rad", min = 0, description = "Joint 1 friction steepness (Gaz phi2)"]
        fc1::Real = 0.039533, [unit = "rad/s", description = "Joint 1 friction offset (Gaz phi3)"]
        Kp2::Real = 522.255, [unit = "N*m/rad", min = 0, description = "Joint 2 proportional gain"]
        Kd2::Real = 69.634, [unit = "N*m*s/rad", min = 0, description = "Joint 2 rate gain"]
        u2max::Real = 87.0, [unit = "N*m", min = 0, description = "Joint 2 torque limit (Franka)"]
        fa2::Real = 0.87224, [unit = "N*m", min = 0, description = "Joint 2 friction level (Gaz phi1)"]
        fb2::Real = 9.0657, [unit = "s/rad", min = 0, description = "Joint 2 friction steepness (Gaz phi2)"]
        fc2::Real = 0.025882, [unit = "rad/s", description = "Joint 2 friction offset (Gaz phi3)"]
        Kp3::Real = 356.466, [unit = "N*m/rad", min = 0, description = "Joint 3 proportional gain"]
        Kd3::Real = 47.529, [unit = "N*m*s/rad", min = 0, description = "Joint 3 rate gain"]
        u3max::Real = 87.0, [unit = "N*m", min = 0, description = "Joint 3 torque limit (Franka)"]
        fa3::Real = 0.64068, [unit = "N*m", min = 0, description = "Joint 3 friction level (Gaz phi1)"]
        fb3::Real = 10.136, [unit = "s/rad", min = 0, description = "Joint 3 friction steepness (Gaz phi2)"]
        fc3::Real = -0.04607, [unit = "rad/s", description = "Joint 3 friction offset (Gaz phi3)"]
        Kp4::Real = 295.549, [unit = "N*m/rad", min = 0, description = "Joint 4 proportional gain"]
        Kd4::Real = 39.406, [unit = "N*m*s/rad", min = 0, description = "Joint 4 rate gain"]
        u4max::Real = 87.0, [unit = "N*m", min = 0, description = "Joint 4 torque limit (Franka)"]
        fa4::Real = 1.2794, [unit = "N*m", min = 0, description = "Joint 4 friction level (Gaz phi1)"]
        fb4::Real = 5.5903, [unit = "s/rad", min = 0, description = "Joint 4 friction steepness (Gaz phi2)"]
        fc4::Real = 0.036194, [unit = "rad/s", description = "Joint 4 friction offset (Gaz phi3)"]
        Kp5::Real = 51.537, [unit = "N*m/rad", min = 0, description = "Joint 5 proportional gain"]
        Kd5::Real = 5.154, [unit = "N*m*s/rad", min = 0, description = "Joint 5 rate gain"]
        u5max::Real = 12.0, [unit = "N*m", min = 0, description = "Joint 5 torque limit (Franka)"]
        fa5::Real = 0.83904, [unit = "N*m", min = 0, description = "Joint 5 friction level (Gaz phi1)"]
        fb5::Real = 8.3469, [unit = "s/rad", min = 0, description = "Joint 5 friction steepness (Gaz phi2)"]
        fc5::Real = 0.026226, [unit = "rad/s", description = "Joint 5 friction offset (Gaz phi3)"]
        Kp6::Real = 53.023, [unit = "N*m/rad", min = 0, description = "Joint 6 proportional gain"]
        Kd6::Real = 5.302, [unit = "N*m*s/rad", min = 0, description = "Joint 6 rate gain"]
        u6max::Real = 12.0, [unit = "N*m", min = 0, description = "Joint 6 torque limit (Franka)"]
        fa6::Real = 0.30301, [unit = "N*m", min = 0, description = "Joint 6 friction level (Gaz phi1)"]
        fb6::Real = 17.133, [unit = "s/rad", min = 0, description = "Joint 6 friction steepness (Gaz phi2)"]
        fc6::Real = -0.021047, [unit = "rad/s", description = "Joint 6 friction offset (Gaz phi3)"]
        Kp7::Real = 41.964, [unit = "N*m/rad", min = 0, description = "Joint 7 proportional gain"]
        Kd7::Real = 4.196, [unit = "N*m*s/rad", min = 0, description = "Joint 7 rate gain"]
        u7max::Real = 12.0, [unit = "N*m", min = 0, description = "Joint 7 torque limit (Franka)"]
        fa7::Real = 0.56489, [unit = "N*m", min = 0, description = "Joint 7 friction level (Gaz phi1)"]
        fb7::Real = 10.336, [unit = "s/rad", min = 0, description = "Joint 7 friction steepness (Gaz phi2)"]
        fc7::Real = 0.0035526, [unit = "rad/s", description = "Joint 7 friction offset (Gaz phi3)"]
        g0::Real = 9.81, [unit = "m/s^2", min = 0, description = "Gravitational acceleration"]
        kf::Real = 1.0, [unit = "1", min = 0, description = "Weight of the Gaz friction feedforward (0 = off)"]
        dt::Real = 0.001, [unit = "s", min = 1.0e-6, description = "Sample period used for the reference rate"]
    end
    @inputs begin
        qr1::Real, [unit = "rad"]
        qr2::Real, [unit = "rad"]
        qr3::Real, [unit = "rad"]
        qr4::Real, [unit = "rad"]
        qr5::Real, [unit = "rad"]
        qr6::Real, [unit = "rad"]
        qr7::Real, [unit = "rad"]
        q1::Real, [unit = "rad"]
        q2::Real, [unit = "rad"]
        q3::Real, [unit = "rad"]
        q4::Real, [unit = "rad"]
        q5::Real, [unit = "rad"]
        q6::Real, [unit = "rad"]
        q7::Real, [unit = "rad"]
        dq1::Real, [unit = "rad/s"]
        dq2::Real, [unit = "rad/s"]
        dq3::Real, [unit = "rad/s"]
        dq4::Real, [unit = "rad/s"]
        dq5::Real, [unit = "rad/s"]
        dq6::Real, [unit = "rad/s"]
        dq7::Real, [unit = "rad/s"]
    end
    @variables begin
        qp1::Real = 0.0, [unit = "rad", description = "Reference of the previous tick"]
        qp2::Real = -0.7853981633974483, [unit = "rad", description = "Reference of the previous tick"]
        qp3::Real = 0.0, [unit = "rad", description = "Reference of the previous tick"]
        qp4::Real = -2.356194490192345, [unit = "rad", description = "Reference of the previous tick"]
        qp5::Real = 0.0, [unit = "rad", description = "Reference of the previous tick"]
        qp6::Real = 1.5707963267948966, [unit = "rad", description = "Reference of the previous tick"]
        qp7::Real = 0.7853981633974483, [unit = "rad", description = "Reference of the previous tick"]
    end
    @outputs begin
        u1::Real = 0.0, [unit = "N*m"]
        u2::Real = -1.7713755491348262, [unit = "N*m"]
        u3::Real = -0.6440003196651126, [unit = "N*m"]
        u4::Real = 18.57359039094953, [unit = "N*m"]
        u5::Real = 0.6338461854898332, [unit = "N*m"]
        u6::Real = 1.6936847301040956, [unit = "N*m"]
        u7::Real = 0.0, [unit = "N*m"]
        e1::Real = 0.0, [unit = "rad"]
        e2::Real = 0.0, [unit = "rad"]
        e3::Real = 0.0, [unit = "rad"]
        e4::Real = 0.0, [unit = "rad"]
        e5::Real = 0.0, [unit = "rad"]
        e6::Real = 0.0, [unit = "rad"]
        e7::Real = 0.0, [unit = "rad"]
        qdr1::Real = 0.0, [unit = "rad/s"]
        qdr2::Real = 0.0, [unit = "rad/s"]
        qdr3::Real = 0.0, [unit = "rad/s"]
        qdr4::Real = 0.0, [unit = "rad/s"]
        qdr5::Real = 0.0, [unit = "rad/s"]
        qdr6::Real = 0.0, [unit = "rad/s"]
        qdr7::Real = 0.0, [unit = "rad/s"]
    end
    @discrete Ts = 0.001 begin
        qdr1 = (qr1 - qp1) / dt
        qp1 = qr1
        qdr2 = (qr2 - qp2) / dt
        qp2 = qr2
        qdr3 = (qr3 - qp3) / dt
        qp3 = qr3
        qdr4 = (qr4 - qp4) / dt
        qp4 = qr4
        qdr5 = (qr5 - qp5) / dt
        qp5 = qr5
        qdr6 = (qr6 - qp6) / dt
        qp6 = qr6
        qdr7 = (qr7 - qp7) / dt
        qp7 = qr7
        # gravity torque of the measured pose (Gaz et al. 2019, generated)
        c1 = cos(q1)
        s1 = sin(q1)
        A1_11 = 1.0
        A1_12 = (1.0 * 0.0 + 0.0 * 0.0)
        A1_13 = (0.0 * 0.0 + 1.0 * 0.0)
        A1_21 = 0.0
        A1_22 = (1.0 * 1.0 + 0.0 * 0.0)
        A1_23 = (0.0 * 1.0 + 1.0 * 0.0)
        A1_31 = 0.0
        A1_32 = (1.0 * 0.0 + 0.0 * 1.0)
        A1_33 = (0.0 * 0.0 + 1.0 * 1.0)
        o1_1 = 0.0 + 0.333 * 0.0
        o1_2 = 0.0 + 0.333 * 0.0
        o1_3 = 0.0 + 0.333 * 1.0
        R1_11 = c1 * A1_11 + s1 * A1_12
        R1_12 = -s1 * A1_11 + c1 * A1_12
        R1_13 = A1_13
        R1_21 = c1 * A1_21 + s1 * A1_22
        R1_22 = -s1 * A1_21 + c1 * A1_22
        R1_23 = A1_23
        R1_31 = c1 * A1_31 + s1 * A1_32
        R1_32 = -s1 * A1_31 + c1 * A1_32
        R1_33 = A1_33
        c2 = cos(q2)
        s2 = sin(q2)
        A2_11 = R1_11
        A2_12 = (0.0 * R1_12 + -1.0 * R1_13)
        A2_13 = (1.0 * R1_12 + 0.0 * R1_13)
        A2_21 = R1_21
        A2_22 = (0.0 * R1_22 + -1.0 * R1_23)
        A2_23 = (1.0 * R1_22 + 0.0 * R1_23)
        A2_31 = R1_31
        A2_32 = (0.0 * R1_32 + -1.0 * R1_33)
        A2_33 = (1.0 * R1_32 + 0.0 * R1_33)
        o2_1 = o1_1
        o2_2 = o1_2
        o2_3 = o1_3
        R2_11 = c2 * A2_11 + s2 * A2_12
        R2_12 = -s2 * A2_11 + c2 * A2_12
        R2_13 = A2_13
        R2_21 = c2 * A2_21 + s2 * A2_22
        R2_22 = -s2 * A2_21 + c2 * A2_22
        R2_23 = A2_23
        R2_31 = c2 * A2_31 + s2 * A2_32
        R2_32 = -s2 * A2_31 + c2 * A2_32
        R2_33 = A2_33
        c3 = cos(q3)
        s3 = sin(q3)
        A3_11 = R2_11
        A3_12 = (0.0 * R2_12 + 1.0 * R2_13)
        A3_13 = (-1.0 * R2_12 + 0.0 * R2_13)
        A3_21 = R2_21
        A3_22 = (0.0 * R2_22 + 1.0 * R2_23)
        A3_23 = (-1.0 * R2_22 + 0.0 * R2_23)
        A3_31 = R2_31
        A3_32 = (0.0 * R2_32 + 1.0 * R2_33)
        A3_33 = (-1.0 * R2_32 + 0.0 * R2_33)
        o3_1 = o2_1 + -0.316 * R2_12
        o3_2 = o2_2 + -0.316 * R2_22
        o3_3 = o2_3 + -0.316 * R2_32
        R3_11 = c3 * A3_11 + s3 * A3_12
        R3_12 = -s3 * A3_11 + c3 * A3_12
        R3_13 = A3_13
        R3_21 = c3 * A3_21 + s3 * A3_22
        R3_22 = -s3 * A3_21 + c3 * A3_22
        R3_23 = A3_23
        R3_31 = c3 * A3_31 + s3 * A3_32
        R3_32 = -s3 * A3_31 + c3 * A3_32
        R3_33 = A3_33
        c4 = cos(q4)
        s4 = sin(q4)
        A4_11 = R3_11
        A4_12 = (0.0 * R3_12 + 1.0 * R3_13)
        A4_13 = (-1.0 * R3_12 + 0.0 * R3_13)
        A4_21 = R3_21
        A4_22 = (0.0 * R3_22 + 1.0 * R3_23)
        A4_23 = (-1.0 * R3_22 + 0.0 * R3_23)
        A4_31 = R3_31
        A4_32 = (0.0 * R3_32 + 1.0 * R3_33)
        A4_33 = (-1.0 * R3_32 + 0.0 * R3_33)
        o4_1 = o3_1 + 0.0825 * R3_11
        o4_2 = o3_2 + 0.0825 * R3_21
        o4_3 = o3_3 + 0.0825 * R3_31
        R4_11 = c4 * A4_11 + s4 * A4_12
        R4_12 = -s4 * A4_11 + c4 * A4_12
        R4_13 = A4_13
        R4_21 = c4 * A4_21 + s4 * A4_22
        R4_22 = -s4 * A4_21 + c4 * A4_22
        R4_23 = A4_23
        R4_31 = c4 * A4_31 + s4 * A4_32
        R4_32 = -s4 * A4_31 + c4 * A4_32
        R4_33 = A4_33
        c5 = cos(q5)
        s5 = sin(q5)
        A5_11 = R4_11
        A5_12 = (0.0 * R4_12 + -1.0 * R4_13)
        A5_13 = (1.0 * R4_12 + 0.0 * R4_13)
        A5_21 = R4_21
        A5_22 = (0.0 * R4_22 + -1.0 * R4_23)
        A5_23 = (1.0 * R4_22 + 0.0 * R4_23)
        A5_31 = R4_31
        A5_32 = (0.0 * R4_32 + -1.0 * R4_33)
        A5_33 = (1.0 * R4_32 + 0.0 * R4_33)
        o5_1 = o4_1 + -0.0825 * R4_11 + 0.384 * R4_12
        o5_2 = o4_2 + -0.0825 * R4_21 + 0.384 * R4_22
        o5_3 = o4_3 + -0.0825 * R4_31 + 0.384 * R4_32
        R5_11 = c5 * A5_11 + s5 * A5_12
        R5_12 = -s5 * A5_11 + c5 * A5_12
        R5_13 = A5_13
        R5_21 = c5 * A5_21 + s5 * A5_22
        R5_22 = -s5 * A5_21 + c5 * A5_22
        R5_23 = A5_23
        R5_31 = c5 * A5_31 + s5 * A5_32
        R5_32 = -s5 * A5_31 + c5 * A5_32
        R5_33 = A5_33
        c6 = cos(q6)
        s6 = sin(q6)
        A6_11 = R5_11
        A6_12 = (0.0 * R5_12 + 1.0 * R5_13)
        A6_13 = (-1.0 * R5_12 + 0.0 * R5_13)
        A6_21 = R5_21
        A6_22 = (0.0 * R5_22 + 1.0 * R5_23)
        A6_23 = (-1.0 * R5_22 + 0.0 * R5_23)
        A6_31 = R5_31
        A6_32 = (0.0 * R5_32 + 1.0 * R5_33)
        A6_33 = (-1.0 * R5_32 + 0.0 * R5_33)
        o6_1 = o5_1
        o6_2 = o5_2
        o6_3 = o5_3
        R6_11 = c6 * A6_11 + s6 * A6_12
        R6_12 = -s6 * A6_11 + c6 * A6_12
        R6_13 = A6_13
        R6_21 = c6 * A6_21 + s6 * A6_22
        R6_22 = -s6 * A6_21 + c6 * A6_22
        R6_23 = A6_23
        R6_31 = c6 * A6_31 + s6 * A6_32
        R6_32 = -s6 * A6_31 + c6 * A6_32
        R6_33 = A6_33
        c7 = cos(q7)
        s7 = sin(q7)
        A7_11 = R6_11
        A7_12 = (0.0 * R6_12 + 1.0 * R6_13)
        A7_13 = (-1.0 * R6_12 + 0.0 * R6_13)
        A7_21 = R6_21
        A7_22 = (0.0 * R6_22 + 1.0 * R6_23)
        A7_23 = (-1.0 * R6_22 + 0.0 * R6_23)
        A7_31 = R6_31
        A7_32 = (0.0 * R6_32 + 1.0 * R6_33)
        A7_33 = (-1.0 * R6_32 + 0.0 * R6_33)
        o7_1 = o6_1 + 0.088 * R6_11
        o7_2 = o6_2 + 0.088 * R6_21
        o7_3 = o6_3 + 0.088 * R6_31
        R7_11 = c7 * A7_11 + s7 * A7_12
        R7_12 = -s7 * A7_11 + c7 * A7_12
        R7_13 = A7_13
        R7_21 = c7 * A7_21 + s7 * A7_22
        R7_22 = -s7 * A7_21 + c7 * A7_22
        R7_23 = A7_23
        R7_31 = c7 * A7_31 + s7 * A7_32
        R7_32 = -s7 * A7_31 + c7 * A7_32
        R7_33 = A7_33
        w1_1 = 4.970684 * (o1_1 + 0.003875 * R1_11 + 0.002081 * R1_12 + -0.04762 * R1_13)
        w1_2 = 4.970684 * (o1_2 + 0.003875 * R1_21 + 0.002081 * R1_22 + -0.04762 * R1_23)
        w2_1 = 0.646926 * (o2_1 + -0.003141 * R2_11 + -0.02872 * R2_12 + 0.003495 * R2_13)
        w2_2 = 0.646926 * (o2_2 + -0.003141 * R2_21 + -0.02872 * R2_22 + 0.003495 * R2_23)
        w3_1 = 3.228604 * (o3_1 + 0.027518 * R3_11 + 0.039252 * R3_12 + -0.066502 * R3_13)
        w3_2 = 3.228604 * (o3_2 + 0.027518 * R3_21 + 0.039252 * R3_22 + -0.066502 * R3_23)
        w4_1 = 3.587895 * (o4_1 + -0.05317 * R4_11 + 0.104419 * R4_12 + 0.027454 * R4_13)
        w4_2 = 3.587895 * (o4_2 + -0.05317 * R4_21 + 0.104419 * R4_22 + 0.027454 * R4_23)
        w5_1 = 1.225946 * (o5_1 + -0.011953 * R5_11 + 0.041065 * R5_12 + -0.038437 * R5_13)
        w5_2 = 1.225946 * (o5_2 + -0.011953 * R5_21 + 0.041065 * R5_22 + -0.038437 * R5_23)
        w6_1 = 1.666555 * (o6_1 + 0.060149 * R6_11 + -0.014117 * R6_12 + -0.010517 * R6_13)
        w6_2 = 1.666555 * (o6_2 + 0.060149 * R6_21 + -0.014117 * R6_22 + -0.010517 * R6_23)
        w7_1 = 0.735522 * (o7_1 + 0.010517 * R7_11 + -0.004252 * R7_12 + 0.061597 * R7_13)
        w7_2 = 0.735522 * (o7_2 + 0.010517 * R7_21 + -0.004252 * R7_22 + 0.061597 * R7_23)
        S7_1 = w7_1
        S7_2 = w7_2
        G7 = g0 * (R7_13 * (S7_2 - 0.735522 * o7_2) - R7_23 * (S7_1 - 0.735522 * o7_1))
        S6_1 = w6_1 + S7_1
        S6_2 = w6_2 + S7_2
        G6 = g0 * (R6_13 * (S6_2 - 2.4020770000000002 * o6_2) - R6_23 * (S6_1 - 2.4020770000000002 * o6_1))
        S5_1 = w5_1 + S6_1
        S5_2 = w5_2 + S6_2
        G5 = g0 * (R5_13 * (S5_2 - 3.628023 * o5_2) - R5_23 * (S5_1 - 3.628023 * o5_1))
        S4_1 = w4_1 + S5_1
        S4_2 = w4_2 + S5_2
        G4 = g0 * (R4_13 * (S4_2 - 7.215918 * o4_2) - R4_23 * (S4_1 - 7.215918 * o4_1))
        S3_1 = w3_1 + S4_1
        S3_2 = w3_2 + S4_2
        G3 = g0 * (R3_13 * (S3_2 - 10.444522000000001 * o3_2) - R3_23 * (S3_1 - 10.444522000000001 * o3_1))
        S2_1 = w2_1 + S3_1
        S2_2 = w2_2 + S3_2
        G2 = g0 * (R2_13 * (S2_2 - 11.091448 * o2_2) - R2_23 * (S2_1 - 11.091448 * o2_1))
        S1_1 = w1_1 + S2_1
        S1_2 = w1_2 + S2_2
        G1 = g0 * (R1_13 * (S1_2 - 16.062132000000002 * o1_2) - R1_23 * (S1_1 - 16.062132000000002 * o1_1))
        e1 = qr1 - q1
        F1 = fa1 / (1.0 + exp(-fb1 * (qdr1 + fc1))) - fa1 / (1.0 + exp(-fb1 * fc1))
        u1 = clamp(Kp1 * e1 + Kd1 * (qdr1 - dq1) + G1 + kf * F1, -u1max, u1max)
        e2 = qr2 - q2
        F2 = fa2 / (1.0 + exp(-fb2 * (qdr2 + fc2))) - fa2 / (1.0 + exp(-fb2 * fc2))
        u2 = clamp(Kp2 * e2 + Kd2 * (qdr2 - dq2) + G2 + kf * F2, -u2max, u2max)
        e3 = qr3 - q3
        F3 = fa3 / (1.0 + exp(-fb3 * (qdr3 + fc3))) - fa3 / (1.0 + exp(-fb3 * fc3))
        u3 = clamp(Kp3 * e3 + Kd3 * (qdr3 - dq3) + G3 + kf * F3, -u3max, u3max)
        e4 = qr4 - q4
        F4 = fa4 / (1.0 + exp(-fb4 * (qdr4 + fc4))) - fa4 / (1.0 + exp(-fb4 * fc4))
        u4 = clamp(Kp4 * e4 + Kd4 * (qdr4 - dq4) + G4 + kf * F4, -u4max, u4max)
        e5 = qr5 - q5
        F5 = fa5 / (1.0 + exp(-fb5 * (qdr5 + fc5))) - fa5 / (1.0 + exp(-fb5 * fc5))
        u5 = clamp(Kp5 * e5 + Kd5 * (qdr5 - dq5) + G5 + kf * F5, -u5max, u5max)
        e6 = qr6 - q6
        F6 = fa6 / (1.0 + exp(-fb6 * (qdr6 + fc6))) - fa6 / (1.0 + exp(-fb6 * fc6))
        u6 = clamp(Kp6 * e6 + Kd6 * (qdr6 - dq6) + G6 + kf * F6, -u6max, u6max)
        e7 = qr7 - q7
        F7 = fa7 / (1.0 + exp(-fb7 * (qdr7 + fc7))) - fa7 / (1.0 + exp(-fb7 * fc7))
        u7 = clamp(Kp7 * e7 + Kd7 * (qdr7 - dq7) + G7 + kf * F7, -u7max, u7max)
    end
end
